        CaptionLine(
          start: Duration(milliseconds: 155811),
          end: Duration(milliseconds: 161131),
          text: 'Then he noticed the old tin box beside the chair.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 161131),
          end: Duration(milliseconds: 163171),
          text: '“What’s in that?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 163171),
          end: Duration(milliseconds: 168499),
          text: 'Uncle Bashir’s hand moved over the lid almost instinctively.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 168499),
          end: Duration(milliseconds: 170659),
          text: '“Old memories.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 170659),
          end: Duration(milliseconds: 174979),
          text: 'The bell rang before Akhlaaq could ask more.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 174979),
          end: Duration(milliseconds: 179734),
          text:
              'At lunch, Hamza discovered that he had forgotten his lunch box.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 180619),
          end: Duration(milliseconds: 185739),
          text:
              'Without a meeting or a lecture, the friends simply shared what they had.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 186689),
          end: Duration(milliseconds: 195467),
          text:
              'Ali divided his sandwich, Fatima offered fruit, Imaan shared paratha and Akhlaaq handed over his juice.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 195911),
          end: Duration(milliseconds: 200467),
          text: 'Ms. Sana saw it from the doorway but did not interrupt.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 200467),
          end: Duration(milliseconds: 206435),
          text:
              'Gratitude had begun to turn into kindness without anyone announcing it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 206435),
          end: Duration(milliseconds: 209924),
          text: 'After school, Akhlaaq passed the gate again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 209924),
          end: Duration(milliseconds: 211785),
          text: 'The tin box was open.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 211785),
          end: Duration(milliseconds: 217194),
          text:
              'For just a second he saw an old black-and-white photograph inside.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 217194),
          end: Duration(milliseconds: 220675),
          text: 'A younger Uncle Bashir stood beside several students.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 221977),
          end: Duration(milliseconds: 228272),
          text: 'One boy looked strangely familiar.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 228272),
          end: Duration(milliseconds: 229403),
          text: 'Before Akhlaaq could focus on the face, the lid closed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 229403),
          end: Duration(milliseconds: 233843),
          text:
              '“Some memories are opened at the right time,” Uncle Bashir said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 233843),
          end: Duration(milliseconds: 240483),
          text:
              'That evening, Akhlaaq asked Dadi whether she knew Bashir Ahmed from Amanpur School.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 240483),
          end: Duration(milliseconds: 242003),
          text: 'Dadi stopped eating.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 242457),
          end: Duration(milliseconds: 244123),
          text: 'Abbu looked up too.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 244123),
          end: Duration(milliseconds: 245923),
          text: '“You mean Uncle Bashir?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 245923),
          end: Duration(milliseconds: 246363),
          text: 'Dadi asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 247104),
          end: Duration(milliseconds: 248571),
          text: '“You know him?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 248991),
          end: Duration(milliseconds: 249971),
          text: 'Abbu laughed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 249971),
          end: Duration(milliseconds: 251451),
          text: '“You never asked.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 251451),
          end: Duration(milliseconds: 255011),
          text: 'Later, Dadi opened an old family album.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 255011),
          end: Duration(milliseconds: 258771),
          text: 'On one faded page stood Abbu as a schoolboy.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 258771),
          end: Duration(milliseconds: 266171),
          text:
              'Beside him was a much younger Uncle Bashir, who had worked at Amanpur School then as a junior gate assistant.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 266339),
          end: Duration(milliseconds: 269031),
          text: 'Beside them stood a smiling teacher.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 269031),
          end: Duration(milliseconds: 272979),
          text: 'Her name had faded until only one word remained clear.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 272979),
          end: Duration(milliseconds: 273939),
          text: 'Farah',
        ),
        CaptionLine(
          start: Duration(milliseconds: 273939),
          end: Duration(milliseconds: 278899),
          text:
              'The next morning, Akhlaaq hurried to the gate with the photograph in his mind.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 279859),
          end: Duration(milliseconds: 283066),
          text: '“Uncle Bashir... was Mrs. Farah your teacher?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 283066),
          end: Duration(milliseconds: 286179),
          text: 'The broom slipped from the old man’s hand.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 286307),
          end: Duration(milliseconds: 289187),
          text: 'For a long moment he said nothing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 289187),
          end: Duration(milliseconds: 294227),
          text: 'Then he opened the tin box and lifted the yellowing envelope.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 294227),
          end: Duration(milliseconds: 295827),
          text: '“No, beta.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 295827),
          end: Duration(milliseconds: 300587),
          text:
              'I was already working here as a junior gate assistant,” he said softly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 300587),
          end: Duration(milliseconds: 303347),
          text: '“Mrs. Farah was your Abbu’s teacher.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 303347),
          end: Duration(milliseconds: 311875),
          text:
              'She treated the staff with the same respect she gave her students, and before she left this school, she trusted me with this.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 313470),
          end: Duration(milliseconds: 315229),
          text: 'Akhlaaq stared at the envelope.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 315229),
          end: Duration(milliseconds: 316248),
          text: '“Can we read it?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 316248),
          end: Duration(milliseconds: 321780),
          text:
              'Uncle Bashir looked toward the children entering through the gate.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 321780),
          end: Duration(milliseconds: 322430),
          text: '“Not yet.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 322430),
          end: Duration(milliseconds: 324706),
          text: 'She gave me one condition.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 324706),
          end: Duration(milliseconds: 326115),
          text: '“What condition?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 326243),
          end: Duration(milliseconds: 329043),
          text: 'He turned the envelope over.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 329043),
          end: Duration(milliseconds: 332843),
          text: 'On the back, in faded handwriting, were the words:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 332843),
          end: Duration(milliseconds: 336963),
          text: 'Open this when the children begin to notice people again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 336963),
          end: Duration(milliseconds: 338963),
          text: 'The morning bell rang.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 339670),
          end: Duration(milliseconds: 340612),
          text: 'Akhlaaq looked at Imaan.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 341083),
          end: Duration(milliseconds: 344203),
          text: 'What exactly had Mrs. Farah been waiting for?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 346211),
          end: Duration(milliseconds: 350211),
          text: 'Challenge of the Day: Learn a Name, Show Respect',
        ),
        CaptionLine(
          start: Duration(milliseconds: 350211),
          end: Duration(milliseconds: 364211),
          text:
              'Mission: Learn the name of one person you regularly see but rarely speak to: a guard, cleaner, driver, helper, librarian, shop worker, neighbour or support staff member.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 364211),
          end: Duration(milliseconds: 369459),
          text:
              'Greet them respectfully and make one small act easier for them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 369459),
          end: Duration(milliseconds: 377812),
          text:
              'Level-Up (Ages 9-12): Use their name respectfully the next time you see them and continue the habit for the week.',
        ),
      ],
    ),
    Story(
      id: 'gratitude_en_03',
      title: 'Ep 3 · The Teacher in the Photograph',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/gratitude.webp',
      audioAsset:
          'assets/audio/en/gratitude/03_the_teacher_in_the_photograph.ogg',
      category: StoryCategory.moral,
      description: 'The Things We Never Notice — episode 3 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 227),
          end: Duration(milliseconds: 988),
          text: 'EPISODE 3',
        ),
        CaptionLine(
          start: Duration(milliseconds: 1531),
          end: Duration(milliseconds: 4247),
          text: 'The Teacher in the Photograph',
        ),
        CaptionLine(
          start: Duration(milliseconds: 4247),
          end: Duration(milliseconds: 10335),
          text:
              'The mystery of Mrs. Farah begins to reveal why some teachers are remembered for decades.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 10335),
          end: Duration(milliseconds: 24157),
          text:
              'By the next morning, Akhlaaq had asked himself at least twenty times what could be inside Mrs. Farah’s letter.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 24157),
          end: Duration(milliseconds: 28303),
          text: 'Uncle Bashir refused to be hurried.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 28303),
          end: Duration(milliseconds: 31623),
          text:
              '“A mystery becomes useless if curiosity makes you disrespect the person guarding it,” he told him with a smile.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 31623),
          end: Duration(milliseconds: 36583),
          text:
              'That day Ms. Sana placed an empty chair at the front of the classroom.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 36583),
          end: Duration(milliseconds: 47463),
          text:
              'She asked the students to close their eyes and remember the first teacher who had helped them hold a pencil, read a word or answer a question without fear.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 47463),
          end: Duration(milliseconds: 53511),
          text:
              'Many students could remember a face or a smile before they could remember a name.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 53511),
          end: Duration(milliseconds: 53512),
          text:
              '“Sometimes,” Ms. Sana said, “we remember the lesson and forget the person who made the lesson possible.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 53512),
          end: Duration(milliseconds: 58311),
          text:
              'During recess, Imaan found an old child’s drawing in the library.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 58311),
          end: Duration(milliseconds: 62751),
          text:
              'A stick-figure teacher was holding the hands of several students.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 62751),
          end: Duration(milliseconds: 68111),
          text:
              'At the bottom, in shaky handwriting, were the words Thank you, Miss Farah.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 68239),
          end: Duration(milliseconds: 75639),
          text:
              'Mrs. Hina explained that former students still asked about Mrs. Farah years after leaving school.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 75639),
          end: Duration(milliseconds: 80699),
          text:
              'Ali decided this was enough evidence to justify becoming a detective.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 80699),
          end: Duration(milliseconds: 91207),
          text:
              'He asked the office assistant for old school records and immediately sneezed so badly that the office staff declared dust his first enemy.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 91207),
          end: Duration(milliseconds: 97207),
          text:
              'Between laughter, they found attendance registers from the years when Mrs. Farah taught.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 97207),
          end: Duration(milliseconds: 102207),
          text: 'That afternoon, Uncle Bashir told them what made her unusual.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 102207),
          end: Duration(milliseconds: 119191),
          text:
              'Mrs. Farah knew students’ names, but she also noticed when a child arrived without lunch, when someone stopped smiling, when a quiet student was being ignored, or when a child who usually tried hard suddenly gave up.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 119191),
          end: Duration(milliseconds: 125646),
          text:
              '“She used to say that children do not need perfect teachers,” Uncle Bashir recalled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 125646),
          end: Duration(milliseconds: 127904),
          text: '“They need teachers who notice them.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 127904),
          end: Duration(milliseconds: 128175),
          text:
              'The next day, a former student named Mr. Kareem spoke at assembly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 128175),
          end: Duration(milliseconds: 139567),
          text:
              'He told the school that he had once been close to leaving education because his family circumstances had become difficult.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 139567),
          end: Duration(milliseconds: 148111),
          text:
              'Mrs. Farah had visited his home, encouraged his family and helped him remain in school.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 148111),
          end: Duration(milliseconds: 151791),
          text: 'Years later, he had become an engineer.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 151791),
          end: Duration(milliseconds: 156751),
          text:
              '“I am not here because she gave me easy marks,” he told the students.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 156751),
          end: Duration(milliseconds: 161431),
          text:
              '“I am here because she refused to let me believe I had no future.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 161431),
          end: Duration(milliseconds: 166671),
          text:
              'The hall applauded, but Imaan and Akhlaaq were watching Uncle Bashir.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 166671),
          end: Duration(milliseconds: 171079),
          text: 'The old man had taken the envelope from his pocket.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 171079),
          end: Duration(milliseconds: 176079),
          text:
              'After school, beneath the neem tree, he finally untied the thread.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 176079),
          end: Duration(milliseconds: 183079),
          text:
              'The first line read: If you are reading this, another generation of children has arrived.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 183079),
          end: Duration(milliseconds: 186079),
          text: 'The children moved closer.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 186079),
          end: Duration(milliseconds: 189811),
          text: 'Mrs. Farah’s letter did not contain a treasure map.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 189811),
          end: Duration(milliseconds: 207807),
          text:
              'It contained memories: reminders that schools are built by more than walls, that successful children stand on the effort of parents, teachers and helpers, and that gratitude begins by noticing names and sacrifices that rarely appear on certificates.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 208015),
          end: Duration(milliseconds: 211815),
          text: 'Then a sudden gust of wind caught the papers.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 211815),
          end: Duration(milliseconds: 214815),
          text: 'The children ran in every direction.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 214815),
          end: Duration(milliseconds: 221855),
          text:
              'They recovered one page from the grass, another from beneath a bench and another beside the football field.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 221855),
          end: Duration(milliseconds: 225975),
          text: 'When they returned, Uncle Bashir counted them twice.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 225975),
          end: Duration(milliseconds: 227855),
          text: '“One is missing.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 227983),
          end: Duration(milliseconds: 231549),
          text: 'They searched until the school began to empty.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 231549),
          end: Duration(milliseconds: 232283),
          text: 'Nothing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 232283),
          end: Duration(milliseconds: 238983),
          text:
              'Near the gate, a Grade 4 girl named Mariam noticed a folded page trapped beneath a bench.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 238983),
          end: Duration(milliseconds: 241183),
          text: 'She picked it up carefully.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 241183),
          end: Duration(milliseconds: 245483),
          text:
              'She could see only one sentence before folding it closed again:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 245483),
          end: Duration(milliseconds: 249451),
          text: 'Never forget the people who helped you become who you are.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 249451),
          end: Duration(milliseconds: 256171),
          text:
              'Mariam placed the page safely in her bag, intending to return it the next morning.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 256171),
          end: Duration(milliseconds: 259591),
          text: 'But none of the older children knew that.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 259591),
          end: Duration(milliseconds: 267331),
          text:
              'For them, the most important page of Mrs. Farah’s message had simply disappeared.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 268559),
          end: Duration(milliseconds: 273146),
          text: 'Challenge of the Day: Thank a Teacher Through Action',
        ),
        CaptionLine(
          start: Duration(milliseconds: 273146),
          end: Duration(milliseconds: 291167),
          text:
              'Mission: Choose one teacher today and show gratitude through behaviour: arrive prepared, complete the work carefully, help organise the classroom, listen without interrupting, or assist another student so the teacher does not have to repeat the same task.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 291167),
          end: Duration(milliseconds: 297167),
          text: 'Level-Up (Ages 9-12): Do the action before saying thank you.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 297967),
          end: Duration(milliseconds: 300767),
          text: 'Let your conduct be part of the gratitude.',
        ),
      ],
    ),
    Story(
      id: 'gratitude_en_04',
      title: 'Ep 4 · The Missing Page',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/gratitude.webp',
      audioAsset: 'assets/audio/en/gratitude/04_the_missing_page.ogg',
      category: StoryCategory.moral,
      description: 'The Things We Never Notice — episode 4 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 94),
          end: Duration(milliseconds: 1112),
          text: 'EPISODE 4',
        ),
        CaptionLine(
          start: Duration(milliseconds: 1112),
          end: Duration(milliseconds: 2894),
          text: 'The Missing Page',
        ),
        CaptionLine(
          start: Duration(milliseconds: 3614),
          end: Duration(milliseconds: 9542),
          text:
              'A lost page returns, but it points toward something hidden inside the school.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 10513),
          end: Duration(milliseconds: 11902),
          text: 'Akhlaaq slept badly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 11902),
          end: Duration(milliseconds: 23902),
          text:
              'Every time he closed his eyes, he imagined Mrs. Farah’s missing page being swept into a drain, torn by rain or thrown away by someone who did not know what it was.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 23902),
          end: Duration(milliseconds: 28823),
          text:
              'The next morning, Ms. Sana called Imaan and Akhlaaq to the Principal’s office.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 28823),
          end: Duration(milliseconds: 30830),
          text: 'Uncle Bashir was already there.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 31790),
          end: Duration(milliseconds: 37310),
          text:
              'Beside him stood Mariam from Grade 4, holding the missing page with both hands.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 38030),
          end: Duration(milliseconds: 40442),
          text: '“I found it near the gate,” she explained.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 40442),
          end: Duration(milliseconds: 46270),
          text:
              '“My mother says that if something does not belong to you, help it find its owner.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 46398),
          end: Duration(milliseconds: 51758),
          text:
              'Uncle Bashir accepted the page as if she had returned something far more valuable than paper.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 52718),
          end: Duration(milliseconds: 56558),
          text: 'Back in class, Ms. Sana placed a small mirror on each desk.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 57198),
          end: Duration(milliseconds: 61278),
          text:
              'The children joked about hairstyles until she asked them to look properly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 62158),
          end: Duration(milliseconds: 67128),
          text:
              '“Every person you see in that mirror was helped into becoming who they are,” she said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 67128),
          end: Duration(milliseconds: 70284),
          text: '“Parents, teachers, friends, helpers, neighbours.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 71264),
          end: Duration(milliseconds: 73006),
          text: 'Nobody grows alone.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 73806),
          end: Duration(milliseconds: 77086),
          text: 'After school, the children returned to Uncle Bashir.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 78046),
          end: Duration(milliseconds: 82366),
          text:
              'With the missing page restored, he continued reading Mrs. Farah’s letter.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 83246),
          end: Duration(milliseconds: 90334),
          text:
              'She had written about gratitude toward those who guide us and about a promise she had made before leaving the school.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 90334),
          end: Duration(milliseconds: 98334),
          text:
              'One sentence caught Imaan’s attention: There is another part of this lesson where I taught for the longest time.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 98334),
          end: Duration(milliseconds: 105334),
          text:
              'Do not search for it until you have learned that gratitude is responsibility, not curiosity.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 106302),
          end: Duration(milliseconds: 108060),
          text: 'Ali’s eyes brightened immediately.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 108060),
          end: Duration(milliseconds: 108982),
          text: '“Another part?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 108982),
          end: Duration(milliseconds: 111662),
          text: 'That sounds like permission to search.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 111662),
          end: Duration(milliseconds: 114970),
          text: '“It sounds like the opposite,” Imaan replied.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 114970),
          end: Duration(milliseconds: 118462),
          text: 'They asked Uncle Bashir what Mrs. Farah meant.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 118462),
          end: Duration(milliseconds: 122229),
          text: 'He admitted that he had never been entirely sure.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 122229),
          end: Duration(milliseconds: 131230),
          text:
              'He knew she had used the old activity room and an older classroom in the far corridor, but both had been locked for years.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 131230),
          end: Duration(milliseconds: 135110),
          text: 'When they returned home, Imaan noticed something else.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 135410),
          end: Duration(milliseconds: 137710),
          text: 'Ammi had been quieter than usual.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 137710),
          end: Duration(milliseconds: 142510),
          text:
              'She sat down halfway through preparing dinner and pressed a hand to her forehead.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 142510),
          end: Duration(milliseconds: 145030),
          text: '“You’re tired,” Imaan said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 145030),
          end: Duration(milliseconds: 145706),
          text: '“I’m fine, beta.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 146238),
          end: Duration(milliseconds: 147588),
          text: 'Just a long day.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 147588),
          end: Duration(milliseconds: 150738),
          text: 'But during dinner, Ammi barely ate.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 150738),
          end: Duration(milliseconds: 156607),
          text:
              'She smiled when anyone asked, then got up to check the kitchen again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 157220),
          end: Duration(milliseconds: 162720),
          text: 'Akhlaaq, still thinking about Mrs. Farah, hardly noticed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 162720),
          end: Duration(milliseconds: 180766),
          text:
              'Later that night, Imaan passed the kitchen and found Ammi leaning against the counter, breathing slowly as if waiting for dizziness to pass.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 180766),
          end: Duration(milliseconds: 183832),
          text: '“Ammi?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 183832),
          end: Duration(milliseconds: 192574),
          text: '“I’m okay,” she repeated, but this time her voice was weaker.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 193767),
          end: Duration(milliseconds: 195558),
          text: 'Imaan called Abbu.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 196454),
          end: Duration(milliseconds: 205134),
          text: 'Within minutes the mystery of Mrs. Farah felt very far away.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 206577),
          end: Duration(milliseconds: 224022),
          text:
              'Abbu helped Ammi sit, Dadi brought water, and the children stood silently while the adults decided she was unwell enough to be checked by a doctor.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 224022),
          end: Duration(milliseconds: 245830),
          text:
              'As Abbu left with Ammi, Akhlaaq noticed the unfinished things around the house: lunch ingredients on the counter, a basket of clean clothes, Dadi’s medicine beside an empty glass, school bottles waiting to be filled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 246078),
          end: Duration(milliseconds: 255078),
          text:
              'For the first time, the house looked exactly the same and completely different.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 255078),
          end: Duration(milliseconds: 263078),
          text:
              'On the dining table, Imaan’s old homework notebook was still open.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 263078),
          end: Duration(milliseconds: 268926),
          text: 'THINGS MY PARENTS DO EVERY DAY.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 270067),
          end: Duration(milliseconds: 273166),
          text: 'Akhlaaq stared at the long list.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 273166),
          end: Duration(milliseconds: 276166),
          text: 'He had thought it was finished.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 276166),
          end: Duration(milliseconds: 288014),
          text:
              'He suddenly realised it had never included what happened when the person doing all those things was no longer able to do them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 288014),
          end: Duration(milliseconds: 306782),
          text: 'Challenge of the Day: Protect What Others Prepare for You',
        ),
        CaptionLine(
          start: Duration(milliseconds: 306782),
          end: Duration(milliseconds: 310982),
          text:
              'Mission: Take responsibility for one thing someone usually prepares or fixes for you: pack your own school bag, fill your bottle, put away clothes, clean your eating place, organise your shoes, or prepare what you need for the next day.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 310982),
          end: Duration(milliseconds: 318128),
          text:
              'Level-Up (Ages 9-12): Keep that responsibility for three days without being reminded.',
        ),
      ],
    ),
    Story(
      id: 'gratitude_en_05',
      title: 'Ep 5 · When the House Went Quiet',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/gratitude.webp',
      audioAsset: 'assets/audio/en/gratitude/05_when_the_house_went_quiet.ogg',
      category: StoryCategory.moral,
      description: 'The Things We Never Notice — episode 5 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 254),
          end: Duration(milliseconds: 1102),
          text: 'EPISODE 5',
        ),
        CaptionLine(
          start: Duration(milliseconds: 1102),
          end: Duration(milliseconds: 3328),
          text: 'When the House Went Quiet',
        ),
        CaptionLine(
          start: Duration(milliseconds: 3328),
          end: Duration(milliseconds: 11262),
          text:
              'The mystery pauses, and the children discover the invisible work inside their own home.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 11262),
          end: Duration(milliseconds: 15142),
          text: 'The next morning did not begin with the smell of parathas.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 15142),
          end: Duration(milliseconds: 22822),
          text:
              'It began with an alarm that nobody had remembered to turn off and a kitchen that seemed unusually large.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 22822),
          end: Duration(milliseconds: 26742),
          text: 'Ammi had been kept in hospital for observation and treatment.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 26862),
          end: Duration(milliseconds: 39590),
          text:
              'Abbu had returned late after making sure she was comfortable, slept only a few hours and was now trying to prepare breakfast, answer a work call and find Dadi’s medicine at the same time.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 40106),
          end: Duration(milliseconds: 43030),
          text: 'Akhlaaq appeared in the hallway holding one sock.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 43550),
          end: Duration(milliseconds: 46150),
          text: '“Ammi—” he began automatically.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 46150),
          end: Duration(milliseconds: 46950),
          text: 'Then he stopped.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 47758),
          end: Duration(milliseconds: 49278),
          text: 'No one laughed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 49703),
          end: Duration(milliseconds: 52358),
          text: 'Imaan found the second sock herself.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 52358),
          end: Duration(milliseconds: 60718),
          text:
              'That morning they forgot one lunch box, over-toasted the bread and nearly left home without a signed school form.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 61892),
          end: Duration(milliseconds: 66318),
          text:
              'Abbu apologised for the rushed morning, but Imaan looked at him differently.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 66318),
          end: Duration(milliseconds: 76446),
          text:
              'He had been at the hospital, answered office messages, spoken to the doctor, checked on Dadi and still made sure the children reached school.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 76446),
          end: Duration(milliseconds: 81366),
          text:
              'At school, Ms. Sana immediately noticed that they were quieter.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 81366),
          end: Duration(milliseconds: 87246),
          text:
              'When she learned Ammi was in hospital, she did not turn it into a classroom announcement.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 87246),
          end: Duration(milliseconds: 94487),
          text:
              'She quietly arranged for missed work to be sent home and told the children they could speak to her if they needed anything.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 96006),
          end: Duration(milliseconds: 97614),
          text: '“JazakAllahu Khaira, Miss,” Imaan said softly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 97963),
          end: Duration(milliseconds: 102934),
          text:
              'Ms. Sana simply squeezed her shoulder and told her to focus on her family.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 102934),
          end: Duration(milliseconds: 106396),
          text: 'Their friends acted just as naturally.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 106396),
          end: Duration(milliseconds: 108467),
          text: 'Fatima shared lunch with Imaan.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 108825),
          end: Duration(milliseconds: 113388),
          text:
              'Ali gave Akhlaaq the worksheet he had missed while distracted.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 113388),
          end: Duration(milliseconds: 117743),
          text:
              'Hamza carried their project materials without making a joke about it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 117743),
          end: Duration(milliseconds: 121581),
          text: 'Gratitude Week had stopped feeling like school homework.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 121581),
          end: Duration(milliseconds: 127114),
          text:
              'At home that afternoon, the children tried to keep the routine moving.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 128377),
          end: Duration(milliseconds: 129123),
          text: 'Imaan folded uniforms.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 129683),
          end: Duration(milliseconds: 134630),
          text:
              'Akhlaaq packed water bottles but forgot the caps and soaked the counter.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 136123),
          end: Duration(milliseconds: 138342),
          text: 'Dadi guided them without taking over.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 138589),
          end: Duration(milliseconds: 146218),
          text:
              'Abbu returned from the hospital, changed clothes and immediately began preparing something simple for dinner.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 146218),
          end: Duration(milliseconds: 148912),
          text: '“Does Ammi do all this every day?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 149897),
          end: Duration(milliseconds: 150718),
          text: 'Akhlaaq asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 153330),
          end: Duration(milliseconds: 154678),
          text: 'Dadi looked at him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 154678),
          end: Duration(milliseconds: 158198),
          text: '“Different people carry different parts of a family.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 158198),
          end: Duration(milliseconds: 163278),
          text:
              'The problem begins when we notice only the part we carry ourselves.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 163278),
          end: Duration(milliseconds: 167566),
          text:
              'The following day, Abbu returned from the hospital with better news.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 167566),
          end: Duration(milliseconds: 173406),
          text:
              '“Alhamdulillah, the doctor says Ammi is improving,” he told them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 173406),
          end: Duration(milliseconds: 178486),
          text:
              '“She needs more rest, but Inn shaa Allah she will be home soon.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 178486),
          end: Duration(milliseconds: 183166),
          text:
              'The children were relieved, yet the house continued teaching them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 183697),
          end: Duration(milliseconds: 187326),
          text: 'Akhlaaq finally learned where the clean towels were kept.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 187882),
          end: Duration(milliseconds: 192414),
          text:
              'Imaan discovered how much planning was hidden inside a simple lunch.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 192414),
          end: Duration(milliseconds: 200654),
          text:
              'Both noticed that Abbu’s work did not stop because the family was having a difficult week; he simply carried more quietly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 200654),
          end: Duration(milliseconds: 206534),
          text:
              'Dadi reminded them that the Qur’an teaches gratitude to Allah and to parents.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 206534),
          end: Duration(milliseconds: 209892),
          text: '“Shukr is not only something we say,” she added.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 209892),
          end: Duration(milliseconds: 215702),
          text:
              '“It should make us more responsible with the blessings Allah has given us.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 215702),
          end: Duration(milliseconds: 221222),
          text:
              'At school, Uncle Bashir did not mention the old letter until Akhlaaq asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 221222),
          end: Duration(milliseconds: 224582),
          text: 'Instead, he handed him a small paper bag.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 224582),
          end: Duration(milliseconds: 226942),
          text: '“Some fruit for your Ammi,” he said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 229045),
          end: Duration(milliseconds: 230990),
          text: '“JazakAllahu Khaira, Uncle Bashir,” Akhlaaq said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 230990),
          end: Duration(milliseconds: 232510),
          text: '“You didn’t have to.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 232510),
          end: Duration(milliseconds: 234590),
          text: '“I know.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 234590),
          end: Duration(milliseconds: 240590),
          text:
              'That answer reminded Akhlaaq of the school cleaner telling them the same thing when they had offered help.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 240590),
          end: Duration(milliseconds: 246510),
          text:
              'Gratitude, he realised, often lived in things nobody was forced to do.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 246510),
          end: Duration(milliseconds: 250718),
          text:
              'As the children were leaving, the school peon called Uncle Bashir.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 250718),
          end: Duration(milliseconds: 255118),
          text: 'A plain envelope had been delivered with no sender’s name.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 255118),
          end: Duration(milliseconds: 257398),
          text: 'Inside was a short note:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 257398),
          end: Duration(milliseconds: 261158),
          text: 'Some promises are still waiting to be fulfilled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 261158),
          end: Duration(milliseconds: 265278),
          text: 'A small silver key fell into Uncle Bashir’s palm.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 265278),
          end: Duration(milliseconds: 267278),
          text: 'His face changed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 267406),
          end: Duration(milliseconds: 270246),
          text: '“I know this key,” he whispered.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 270246),
          end: Duration(milliseconds: 271495),
          text: '“From where?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 271495),
          end: Duration(milliseconds: 272606),
          text: 'Ali asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 272606),
          end: Duration(milliseconds: 275606),
          text: 'Uncle Bashir closed his fingers around it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 275606),
          end: Duration(milliseconds: 279206),
          text: '“I haven’t seen it for more than twenty years.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 279206),
          end: Duration(milliseconds: 285646),
          text:
              'For the first time since Ammi became ill, Akhlaaq felt the old mystery pull at him again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 285646),
          end: Duration(milliseconds: 287374),
          text: 'Someone had sent the key now.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 287374),
          end: Duration(milliseconds: 290374),
          text: 'Someone knew about Mrs. Farah’s promise.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 290374),
          end: Duration(milliseconds: 296550),
          text:
              'And whoever it was had been watching the story from much closer than they realised.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 296550),
          end: Duration(milliseconds: 307342),
          text: 'Challenge of the Day: Carry One Family Responsibility',
        ),
        CaptionLine(
          start: Duration(milliseconds: 307342),
          end: Duration(milliseconds: 321200),
          text:
              'Mission: Choose one household responsibility that normally belongs to someone else and carry it properly today: set and clear the table, fold laundry, prepare school items, refill water, help a younger sibling, organise a shared space, or assist an elder.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 321200),
          end: Duration(milliseconds: 326006),
          text: 'Level-Up (Ages 9-12): Do not treat it as a one-time favour.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 326766),
          end: Duration(milliseconds: 330392),
          text: 'Repeat the same responsibility for the next three days.',
        ),
      ],
    ),
    Story(
      id: 'gratitude_en_06',
      title: 'Ep 6 · The Work We Never Saw',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/gratitude.webp',
      audioAsset: 'assets/audio/en/gratitude/06_the_work_we_never_saw.ogg',
      category: StoryCategory.moral,
      description: 'The Things We Never Notice — episode 6 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 198),
          end: Duration(milliseconds: 1324),
          text: 'EPISODE 6',
        ),
        CaptionLine(
          start: Duration(milliseconds: 1324),
          end: Duration(milliseconds: 3718),
          text: 'The Work We Never Saw',
        ),
        CaptionLine(
          start: Duration(milliseconds: 3718),
          end: Duration(milliseconds: 8958),
          text:
              'While Ammi recovers, gratitude becomes a habit of sharing responsibility.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 9278),
          end: Duration(milliseconds: 11838),
          text: 'Ammi returned home two days later.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 11838),
          end: Duration(milliseconds: 16514),
          text:
              '“Alhamdulillah,” Dadi said as she welcomed her, and the children echoed her with relieved smiles.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 16886),
          end: Duration(milliseconds: 23886),
          text:
              'But Dadi made one rule very clear: returning home did not mean returning to work.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 23886),
          end: Duration(milliseconds: 26886),
          text: 'For once, Ammi was the person being told to sit down.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 26886),
          end: Duration(milliseconds: 29886),
          text: 'The family reorganised itself.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 30123),
          end: Duration(milliseconds: 32886),
          text: 'Abbu handled groceries and meals when he could.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 33210),
          end: Duration(milliseconds: 35399),
          text: 'Imaan prepared school bags and helped Dadi.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 37432),
          end: Duration(milliseconds: 41554),
          text:
              'Akhlaaq took responsibility for water bottles, shoes and clearing the table.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 41554),
          end: Duration(milliseconds: 43914),
          text: 'The first day he forgot half of it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 43914),
          end: Duration(milliseconds: 47794),
          text: 'The second day he remembered before anyone asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 47794),
          end: Duration(milliseconds: 52594),
          text:
              'By the third, he was annoyed when someone moved his carefully arranged bottles.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 52594),
          end: Duration(milliseconds: 56314),
          text: '“You’re becoming Ammi,” Imaan teased.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 56314),
          end: Duration(milliseconds: 61642),
          text:
              '“I finally understand why she keeps telling us where things belong,” he replied.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 61892),
          end: Duration(milliseconds: 66982),
          text:
              'Ammi watched from the sofa with a smile that was part pride and part exhaustion.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 67711),
          end: Duration(milliseconds: 69462),
          text: '“Mashaa Allah,” she said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 69462),
          end: Duration(milliseconds: 74582),
          text:
              '“I think this house has discovered that water bottles can be filled without me.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 75542),
          end: Duration(milliseconds: 76662),
          text: 'Akhlaaq grinned.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 76662),
          end: Duration(milliseconds: 80430),
          text: 'At school, the children noticed the same pattern.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 80430),
          end: Duration(milliseconds: 85030),
          text: 'A clean corridor did not happen by itself.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 85030),
          end: Duration(milliseconds: 89390),
          text: 'Sports equipment did not return itself to the cupboard.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 89390),
          end: Duration(milliseconds: 92990),
          text: 'Library books did not repair their own covers.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 92990),
          end: Duration(milliseconds: 96630),
          text: 'The water cooler did not check itself.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 96758),
          end: Duration(milliseconds: 99758),
          text: 'Someone was always carrying a responsibility.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 99758),
          end: Duration(milliseconds: 103758),
          text: 'This made the silver key feel different too.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 103758),
          end: Duration(milliseconds: 107758),
          text: 'Ali wanted to try it in every lock immediately.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 108485),
          end: Duration(milliseconds: 109758),
          text: 'Imaan refused.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 109758),
          end: Duration(milliseconds: 113758),
          text: '“If it belongs to the school, we ask permission.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 113758),
          end: Duration(milliseconds: 118370),
          text:
              'The Principal listened to their story and examined the silver key.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 118370),
          end: Duration(milliseconds: 124190),
          text:
              'He agreed that they could visit the old activity room only with Uncle Bashir present.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 124190),
          end: Duration(milliseconds: 131484),
          text:
              'The room itself still belonged to the school, so he brought the school’s old master key from the office.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 131484),
          end: Duration(milliseconds: 135391),
          text: 'After school, the old master key resisted at first.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 135391),
          end: Duration(milliseconds: 137376),
          text: 'Then the lock turned.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 137376),
          end: Duration(milliseconds: 150712),
          text:
              'The door opened onto a room full of forgotten objects: art boards, science models, old trophies, a dusty piano and boxes labelled with school years.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 150712),
          end: Duration(milliseconds: 155785),
          text:
              'In the corner stood a small wooden chest with a narrow silver lock.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 155785),
          end: Duration(milliseconds: 164182),
          text:
              'Unlike the rest of the room, the chest had a faint clean mark across its dusty lid, as though someone had touched it recently.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 165182),
          end: Duration(milliseconds: 168862),
          text: '“Someone has touched this recently,” Imaan said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 168862),
          end: Duration(milliseconds: 171542),
          text: 'Uncle Bashir looked unsettled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 171542),
          end: Duration(milliseconds: 175222),
          text: 'Uncle Bashir slid the silver key into the chest.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 175222),
          end: Duration(milliseconds: 176462),
          text: 'It turned smoothly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 176630),
          end: Duration(milliseconds: 185630),
          text:
              'Inside were photographs, handmade cards, certificates and a leather diary with Mrs. Farah’s name written across the cover.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 185630),
          end: Duration(milliseconds: 188842),
          text: 'The diary was not filled with test marks.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 188842),
          end: Duration(milliseconds: 202918),
          text:
              'It contained short observations about children: helped a new student; told the truth when afraid; shared lunch; stayed behind to help clean; encouraged a classmate who failed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 202918),
          end: Duration(milliseconds: 206518),
          text: '“She remembered character,” Imaan whispered.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 206518),
          end: Duration(milliseconds: 208398),
          text: 'Uncle Bashir nodded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 208398),
          end: Duration(milliseconds: 210278),
          text: '“More than scores.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 210278),
          end: Duration(milliseconds: 213118),
          text: 'A sealed envelope slipped from the diary.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 213118),
          end: Duration(milliseconds: 219566),
          text:
              'On the front, in Mrs. Farah’s handwriting, were the words: For Shazia, if she ever returns.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 219566),
          end: Duration(milliseconds: 224566),
          text:
              'Before anyone touched it, Uncle Bashir placed his hand over the envelope.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 224566),
          end: Duration(milliseconds: 227566),
          text: '“Not ours to open,” he said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 227566),
          end: Duration(milliseconds: 231566),
          text: '“If Shazia ever returns, this belongs to her.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 231566),
          end: Duration(milliseconds: 235566),
          text: 'Ali groaned, but this time Akhlaaq understood.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 235566),
          end: Duration(milliseconds: 239878),
          text: 'A clue was not permission to forget responsibility.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 239878),
          end: Duration(milliseconds: 245532),
          text:
              'As they returned the diary to the chest, Imaan noticed an old photograph beneath it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 245532),
          end: Duration(milliseconds: 248694),
          text: 'Mrs. Farah stood beside another young teacher.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 249494),
          end: Duration(milliseconds: 256502),
          text:
              'The photograph had been damaged with age, and a torn corner had taken part of the second woman’s face with it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 256502),
          end: Duration(milliseconds: 260022),
          text: 'The damage looked accidental, not deliberate.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 260022),
          end: Duration(milliseconds: 263342),
          text: 'On the back, only part of one sentence remained:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 263342),
          end: Duration(milliseconds: 266342),
          text: '...I hope one day you can forgive me.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 266342),
          end: Duration(milliseconds: 268762),
          text: 'The children looked at Uncle Bashir.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 268762),
          end: Duration(milliseconds: 270262),
          text: 'He had gone pale.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 270262),
          end: Duration(milliseconds: 272356),
          text: '“Who was standing beside Mrs. Farah?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 273842),
          end: Duration(milliseconds: 274782),
          text: 'Imaan asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 274782),
          end: Duration(milliseconds: 280470),
          text:
              'Before he answered, the sound of a car stopping outside the school drifted through the open window.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 280470),
          end: Duration(milliseconds: 285470),
          text: 'Challenge of the Day: Do the Job That Is “Not Mine”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 285470),
          end: Duration(milliseconds: 302438),
          text:
              'Mission: When you see a small useful task that safely needs doing, help even if nobody assigned it to you: pick up litter, return equipment, stack chairs, carry books, wipe a shared table, or help restore a space after an activity.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 302438),
          end: Duration(milliseconds: 311438),
          text:
              'Level-Up (Ages 9-12): Choose a task that benefits everyone but gives you no personal reward or recognition.',
        ),
      ],
    ),
    Story(
      id: 'gratitude_en_07',
      title: 'Ep 7 · The Silver Key',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/gratitude.webp',
      audioAsset: 'assets/audio/en/gratitude/07_the_silver_key.ogg',
      category: StoryCategory.moral,
      description: 'The Things We Never Notice — episode 7 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 0),
          end: Duration(milliseconds: 1078),
          text: 'EPISODE 7',
        ),
        CaptionLine(
          start: Duration(milliseconds: 1078),
          end: Duration(milliseconds: 2878),
          text: 'The Silver Key',
        ),
        CaptionLine(
          start: Duration(milliseconds: 2878),
          end: Duration(milliseconds: 8559),
          text:
              'A hidden room reveals that Mrs. Farah had been recording kindness for years.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 8559),
          end: Duration(milliseconds: 13266),
          text:
              'The car outside the school was gone before the children reached the gate.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 13266),
          end: Duration(milliseconds: 18621),
          text:
              'Uncle Bashir would say only that he had seen someone he had not expected to see again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 18621),
          end: Duration(milliseconds: 24606),
          text:
              'That answer made Ali suspicious of every car in Amanpur for the next twenty-four hours.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 24606),
          end: Duration(milliseconds: 24814),
          text:
              'The following afternoon, the children returned to the activity room with permission.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 24814),
          end: Duration(milliseconds: 32814),
          text:
              'This time they looked more carefully instead of rushing from clue to clue.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 32814),
          end: Duration(milliseconds: 46298),
          text:
              'The diary showed that Mrs. Farah had deliberately recorded small ethical acts because she believed character was part of education.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 46298),
          end: Duration(milliseconds: 56990),
          text:
              'She used paper stars to recognise kindness, honesty and responsibility, not expensive prizes.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 56990),
          end: Duration(milliseconds: 64542),
          text:
              'Inside another box were dozens of thank-you cards from former students.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 64750),
          end: Duration(milliseconds: 70750),
          text: 'One said, Thank you for believing in me when nobody else did.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 70750),
          end: Duration(milliseconds: 76750),
          text:
              'Another thanked her for helping a family through a difficult year.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 76750),
          end: Duration(milliseconds: 83750),
          text:
              'A third contained only five words: You noticed when I disappeared.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 84718),
          end: Duration(milliseconds: 86493),
          text: 'Imaan read that one twice.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 86493),
          end: Duration(milliseconds: 95631),
          text:
              'Uncle Bashir explained that some children slowly stop participating when life becomes difficult.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 95631),
          end: Duration(milliseconds: 101358),
          text:
              'Mrs. Farah had been unusually good at noticing the quiet changes.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 103028),
          end: Duration(milliseconds: 109646),
          text:
              'Akhlaaq thought of Ms. Sana noticing immediately that something was wrong when Ammi went to hospital.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 110766),
          end: Duration(milliseconds: 115566),
          text: 'Near the back of the diary, they found a small brass badge.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 116286),
          end: Duration(milliseconds: 121886),
          text: 'The words THE CHILDREN WHO NOTICE were engraved across it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 121886),
          end: Duration(milliseconds: 123831),
          text: '“What is this?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 123831),
          end: Duration(milliseconds: 124526),
          text: 'Akhlaaq asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 124654),
          end: Duration(milliseconds: 126654),
          text: 'Uncle Bashir smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 126654),
          end: Duration(milliseconds: 130154),
          text: '“Mrs. Farah once ran a small character group.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 130154),
          end: Duration(milliseconds: 132654),
          text: 'Children earned no prizes.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 132654),
          end: Duration(milliseconds: 136654),
          text:
              'Their job was to notice who needed help and do something useful.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 136654),
          end: Duration(milliseconds: 139654),
          text: 'A folded note lay beneath the badge.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 139654),
          end: Duration(milliseconds: 143154),
          text: 'A school is never built with bricks alone.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 143154),
          end: Duration(milliseconds: 146023),
          text: 'Find the people who built lives here.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 146023),
          end: Duration(milliseconds: 150142),
          text: 'The clue led them to old class photographs and staff records.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 150702),
          end: Duration(milliseconds: 154195),
          text: 'One woman appeared repeatedly beside Mrs. Farah.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 154195),
          end: Duration(milliseconds: 157571),
          text: 'The name under the photograph was Shazia Rahman.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 157571),
          end: Duration(milliseconds: 164062),
          text:
              'Uncle Bashir finally told them that Mrs. Shazia had been Mrs. Farah’s closest colleague.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 164062),
          end: Duration(milliseconds: 170190),
          text:
              'They had worked together for years and then stopped speaking after a painful misunderstanding.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 170190),
          end: Duration(milliseconds: 173790),
          text: 'Neither repaired the relationship before Mrs. Farah retired.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 173790),
          end: Duration(milliseconds: 176390),
          text: '“Where is Mrs. Shazia now?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 176835),
          end: Duration(milliseconds: 177390),
          text: 'Imaan asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 177390),
          end: Duration(milliseconds: 180310),
          text: '“I don’t know,” Uncle Bashir replied.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 180310),
          end: Duration(milliseconds: 183510),
          text: '“I have not seen her in twenty years.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 183510),
          end: Duration(milliseconds: 186864),
          text: 'He was closing the diary when a shadow crossed the doorway.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 186864),
          end: Duration(milliseconds: 191558),
          text:
              'An elderly woman in a light blue shawl stood at the end of the corridor.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 191558),
          end: Duration(milliseconds: 196558),
          text:
              'She looked directly at the leather diary, then at Uncle Bashir.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 197499),
          end: Duration(milliseconds: 200558),
          text: '“Assalam o Alaikum, Bashir,” she said softly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 200558),
          end: Duration(milliseconds: 202558),
          text: '“Is it still safe?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 202558),
          end: Duration(milliseconds: 205094),
          text: 'Uncle Bashir stared at her.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 205094),
          end: Duration(milliseconds: 208727),
          text: 'For several seconds, he could not speak.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 208727),
          end: Duration(milliseconds: 211566),
          text: '“Wa Alaikum Assalam,” he managed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 212286),
          end: Duration(milliseconds: 215335),
          text: 'Then he whispered one name.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 215335),
          end: Duration(milliseconds: 216167),
          text: '“Shazia?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 216167),
          end: Duration(milliseconds: 220324),
          text: 'Challenge of the Day: Protect a Trust',
        ),
        CaptionLine(
          start: Duration(milliseconds: 220324),
          end: Duration(milliseconds: 227494),
          text:
              'Mission: Return one borrowed item today in the same or better condition than you received it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 227494),
          end: Duration(milliseconds: 236494),
          text:
              'If you have promised to keep, carry, deliver or care for something, complete that responsibility without needing a reminder.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 236494),
          end: Duration(milliseconds: 244345),
          text:
              'Level-Up (Ages 9-12): Choose one trust you have been careless with before and repair that habit this week.',
        ),
      ],
    ),
    Story(
      id: 'gratitude_en_08',
      title: 'Ep 8 · The Woman Who Came Back',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/gratitude.webp',
      audioAsset: 'assets/audio/en/gratitude/08_the_woman_who_came_back.ogg',
      category: StoryCategory.moral,
      description: 'The Things We Never Notice — episode 8 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 117),
          end: Duration(milliseconds: 1196),
          text: 'EPISODE 8',
        ),
        CaptionLine(
          start: Duration(milliseconds: 1196),
          end: Duration(milliseconds: 3757),
          text: 'The Woman Who Came Back',
        ),
        CaptionLine(
          start: Duration(milliseconds: 3757),
          end: Duration(milliseconds: 8917),
          text:
              'The person behind the torn photograph finally tells her side of the story.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 8917),
          end: Duration(milliseconds: 12917),
          text: 'Mrs. Shazia returned to the school the following morning.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 12917),
          end: Duration(milliseconds: 15517),
          text: 'This time she did not leave.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 16844),
          end: Duration(milliseconds: 20117),
          text:
              '“Assalam o Alaikum,” she said as she entered the old activity room.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 21724),
          end: Duration(milliseconds: 26750),
          text:
              '“Wa Alaikum Assalam,” came the reply from Uncle Bashir, the Principal, Imaan and Akhlaaq.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 27405),
          end: Duration(milliseconds: 39445),
          text:
              'She sat with them, and her eyes moved slowly across Mrs. Farah’s diary, the paper stars and the photographs as though every object carried a voice from another time.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 39445),
          end: Duration(milliseconds: 41654),
          text: '“I sent the key,” she admitted.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 41654),
          end: Duration(milliseconds: 44384),
          text: '“And I came here once before I sent it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 44384),
          end: Duration(milliseconds: 49228),
          text:
              'The Principal allowed me to visit the old room quietly after school.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 49228),
          end: Duration(milliseconds: 55144),
          text:
              'I touched the chest, but I could not bring myself to open it or face anyone.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 55144),
          end: Duration(milliseconds: 58703),
          text: 'That was the mark you saw in the dust.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 58703),
          end: Duration(milliseconds: 65981),
          text: 'The car Uncle Bashir noticed was mine.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 65981),
          end: Duration(milliseconds: 74901),
          text:
              'Ali, who had been allowed to join them with Fatima, looked delighted that at least one mystery had a clean answer.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 74901),
          end: Duration(milliseconds: 79981),
          text:
              'Mrs. Shazia explained that she and Mrs. Farah had once been very close.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 79989),
          end: Duration(milliseconds: 88429),
          text:
              'During a difficult school year, a misunderstanding developed over a decision involving students and staff.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 88429),
          end: Duration(milliseconds: 91989),
          text: 'Shazia believed Farah did not trust her.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 91989),
          end: Duration(milliseconds: 96109),
          text: 'Farah believed Shazia had deliberately withdrawn.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 96109),
          end: Duration(milliseconds: 101787),
          text:
              'Neither asked the other the simple question that could have cleared the matter.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 101787),
          end: Duration(milliseconds: 103502),
          text: 'Days became weeks.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 103502),
          end: Duration(milliseconds: 105447),
          text: 'Weeks became months.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 105447),
          end: Duration(milliseconds: 110241),
          text: 'Pride made each person wait for the other to move first.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 110241),
          end: Duration(milliseconds: 115296),
          text:
              '“By the time I wanted to repair it,” Mrs. Shazia said, “I had moved away.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 115296),
          end: Duration(milliseconds: 116983),
          text: 'Then life became busy.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 116983),
          end: Duration(milliseconds: 121937),
          text: 'I kept telling myself I would return next year.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 121937),
          end: Duration(milliseconds: 124250),
          text: 'She looked down at the diary.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 124250),
          end: Duration(milliseconds: 128618),
          text: '“Next year is a dangerous place to store an apology.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 128618),
          end: Duration(milliseconds: 131165),
          text: 'The children became quiet.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 131165),
          end: Duration(milliseconds: 137965),
          text:
              'Mrs. Shazia had eventually written a letter asking forgiveness, but she never sent it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 137965),
          end: Duration(milliseconds: 141533),
          text: 'Years later, she learned that Mrs. Farah had passed away.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 141533),
          end: Duration(milliseconds: 149093),
          text:
              'The unsent letter became something she carried with her rather than something that could repair the past.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 149093),
          end: Duration(milliseconds: 155745),
          text:
              'Then Uncle Bashir brought out the sealed envelope they had found inside Mrs. Farah’s diary.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 155745),
          end: Duration(milliseconds: 159653),
          text: 'It was addressed by name: For Shazia, if she ever returns.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 161301),
          end: Duration(milliseconds: 167381),
          text:
              'Mrs. Shazia’s hands began to tremble as she opened the envelope and read it silently.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 167381),
          end: Duration(milliseconds: 168861),
          text: 'Tears filled her eyes.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 168861),
          end: Duration(milliseconds: 171141),
          text: '“What does it say?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 171706),
          end: Duration(milliseconds: 173261),
          text: 'Imaan asked gently.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 173261),
          end: Duration(milliseconds: 176581),
          text: 'Mrs. Shazia smiled through the tears.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 176581),
          end: Duration(milliseconds: 179781),
          text: '“It says, ‘I never stopped calling you my friend.’”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 179829),
          end: Duration(milliseconds: 182829),
          text: 'Nobody rushed to fill the silence.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 182829),
          end: Duration(milliseconds: 189829),
          text:
              'Later, Mrs. Shazia walked through the garden and stopped at an old rose bush Mrs. Farah had planted.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 189829),
          end: Duration(milliseconds: 198829),
          text:
              'She said that gratitude sometimes meant recognising the value of a relationship before pride turned time into distance.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 199797),
          end: Duration(milliseconds: 206037),
          text:
              '“I kept thinking I would thank Allah for this friendship properly when I repaired it,” she said.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 206037),
          end: Duration(milliseconds: 213077),
          text:
              '“I should have been grateful enough to take the first good step while I still could.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 213077),
          end: Duration(milliseconds: 217237),
          text: 'At home, the lesson felt unexpectedly close.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 217365),
          end: Duration(milliseconds: 224945),
          text:
              'Ammi was recovering well, but everyone had kept some of the responsibilities they had taken during her illness.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 225503),
          end: Duration(milliseconds: 227845),
          text: 'Akhlaaq still filled the bottles.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 228293),
          end: Duration(milliseconds: 231205),
          text: 'Imaan still prepared her own uniform.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 231520),
          end: Duration(milliseconds: 236565),
          text:
              'Abbu had begun setting aside one evening task so Ammi could rest.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 236565),
          end: Duration(milliseconds: 239045),
          text: '“Why are we still doing all this?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 239365),
          end: Duration(milliseconds: 241413),
          text: 'Akhlaaq asked playfully.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 242066),
          end: Duration(milliseconds: 243373),
          text: 'Ammi smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 243373),
          end: Duration(milliseconds: 254533),
          text:
              '“Because if gratitude disappears the moment a difficulty ends, perhaps we only learned fear of losing something, not gratitude for having it.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 254533),
          end: Duration(milliseconds: 259701),
          text:
              'The next day, Mrs. Shazia brought one final sealed packet to the school.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 259701),
          end: Duration(milliseconds: 264981),
          text:
              '“Farah gave this to me before our friendship broke,” she told Uncle Bashir.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 264981),
          end: Duration(milliseconds: 269341),
          text: '“I was supposed to return it if I ever came back.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 269341),
          end: Duration(milliseconds: 271406),
          text: 'Across the front were the words:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 271406),
          end: Duration(milliseconds: 276321),
          text: 'For the children who choose kindness when nobody is watching.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 276321),
          end: Duration(milliseconds: 278670),
          text: 'Uncle Bashir looked toward Imaan and Akhlaaq.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 279669),
          end: Duration(milliseconds: 283349),
          text: '“I think,” he said, “we are almost ready.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 285213),
          end: Duration(milliseconds: 289309),
          text: 'Challenge of the Day: Take the First Good Step',
        ),
        CaptionLine(
          start: Duration(milliseconds: 289809),
          end: Duration(milliseconds: 305637),
          text:
              'Mission: If there is a safe relationship in which you have been rude, distant or stubborn, take one respectful step today: apologise, return something, greet the person, stop an unkind joke, or offer help.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 305637),
          end: Duration(milliseconds: 315637),
          text:
              'Level-Up (Ages 9-12): Do not wait for the other person to make the first move if you already know what your own right action should be.',
        ),
      ],
    ),
    Story(
      id: 'gratitude_en_09',
      title: 'Ep 9 · While They Can Hear You',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/gratitude.webp',
      audioAsset: 'assets/audio/en/gratitude/09_while_they_can_hear_you.ogg',
      category: StoryCategory.moral,
      description: 'The Things We Never Notice — episode 9 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 0),
          end: Duration(milliseconds: 898),
          text: 'EPISODE 9',
        ),
        CaptionLine(
          start: Duration(milliseconds: 898),
          end: Duration(milliseconds: 3681),
          text: 'While They Can Hear You',
        ),
        CaptionLine(
          start: Duration(milliseconds: 3681),
          end: Duration(milliseconds: 8681),
          text: 'Gratitude becomes words and actions before it becomes regret.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 8681),
          end: Duration(milliseconds: 15181),
          text:
              'The next morning, Ms. Sana entered the classroom carrying a stack of plain envelopes.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 15181),
          end: Duration(milliseconds: 18181),
          text: '“No essay today,” she announced.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 18181),
          end: Duration(milliseconds: 19981),
          text: 'The class cheered.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 19981),
          end: Duration(milliseconds: 22181),
          text: '“No worksheet either.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 22181),
          end: Duration(milliseconds: 23649),
          text: 'The cheering became louder.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 23649),
          end: Duration(milliseconds: 29649),
          text:
              '“You are going to write a real letter to someone you have never properly thanked.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 29649),
          end: Duration(milliseconds: 32766),
          text: 'The room slowly became quiet.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 32766),
          end: Duration(milliseconds: 36532),
          text: 'The task was harder than it sounded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 36532),
          end: Duration(milliseconds: 41990),
          text: 'Hamza chose his grandfather, who had taught him how to pray.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 43617),
          end: Duration(milliseconds: 46697),
          text: 'Fatima chose an older sister who helped her study.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 47101),
          end: Duration(milliseconds: 50834),
          text: 'Imaan knew immediately that she wanted to write to Ammi.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 51851),
          end: Duration(milliseconds: 55780),
          text: 'Akhlaaq sat for a long time before writing a name.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 55780),
          end: Duration(milliseconds: 56577),
          text: 'Abbu.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 56577),
          end: Duration(milliseconds: 66220),
          text:
              'He realised that he thanked Abbu for things—new shoes, a ride, a cricket bat—but rarely for the work that made those things possible.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 66220),
          end: Duration(milliseconds: 72937),
          text:
              'He began his letter with one sentence: Thank you for working hard even when nobody sees it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 72937),
          end: Duration(milliseconds: 76233),
          text: 'At home, Imaan gave Ammi her letter first.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 76233),
          end: Duration(milliseconds: 91935),
          text:
              'She wrote about the mornings she had mistaken for ordinary, about lunches that appeared as if by magic, and about the hospital days when the house taught her how many small acts had been holding the family together.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 91935),
          end: Duration(milliseconds: 93800),
          text: 'At the end she wrote, “JazakAllahu Khaira, Ammi.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 95898),
          end: Duration(milliseconds: 98113),
          text: 'Alhamdulillah for you.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 99878),
          end: Duration(milliseconds: 101095),
          text: 'Ammi hugged her.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 101095),
          end: Duration(milliseconds: 102447),
          text: '“You noticed.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 102447),
          end: Duration(milliseconds: 106161),
          text: '“I’m sorry it took me so long.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 106512),
          end: Duration(milliseconds: 109321),
          text: 'Abbu read Akhlaaq’s letter quietly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 109321),
          end: Duration(milliseconds: 115981),
          text:
              'When he reached the line about unseen work, he folded the paper and pulled his son into a hug.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 116434),
          end: Duration(milliseconds: 122761),
          text:
              'Akhlaaq had prepared a joke in case the moment became emotional, but for once he did not use it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 123489),
          end: Duration(milliseconds: 129829),
          text:
              'At school, students began adding short notes to a Gratitude Wall.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 129829),
          end: Duration(milliseconds: 131929),
          text: 'Some thanked teachers.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 131929),
          end: Duration(milliseconds: 134009),
          text: 'Some thanked friends.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 134009),
          end: Duration(milliseconds: 136529),
          text: 'Others thanked school helpers.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 136529),
          end: Duration(milliseconds: 141609),
          text:
              'One younger child thanked whoever had returned his lost pencil.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 141609),
          end: Duration(milliseconds: 148417),
          text:
              'Uncle Bashir stood before the wall for a long time when he found his own name there.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 148417),
          end: Duration(milliseconds: 151217),
          text: 'Mrs. Shazia also wrote a letter.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 151217),
          end: Duration(milliseconds: 153977),
          text: 'Hers was addressed to Mrs. Farah.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 153977),
          end: Duration(milliseconds: 165425),
          text:
              'She could no longer place it into her friend’s hands, but she decided the children should see one important truth: gratitude delayed too long can become regret.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 165425),
          end: Duration(milliseconds: 170425),
          text:
              'The sealed packet Mrs. Shazia had brought was opened in the old classroom.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 170425),
          end: Duration(milliseconds: 176425),
          text:
              'Inside lay a small fountain pen and one final message from Mrs. Farah:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 176425),
          end: Duration(milliseconds: 182425),
          text:
              'If children have learned to notice kindness, let them continue the story.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 183393),
          end: Duration(milliseconds: 187902),
          text:
              'The Principal decided that the final message should be read during Gratitude Day.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 187902),
          end: Duration(milliseconds: 193535),
          text:
              'Until then, the children were asked to do something more difficult than solving clues.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 193535),
          end: Duration(milliseconds: 196113),
          text: 'They were asked to keep noticing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 196113),
          end: Duration(milliseconds: 206681),
          text:
              'That afternoon, Akhlaaq saw the cleaner carrying a bucket and automatically moved the chairs out of the way before being asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 207056),
          end: Duration(milliseconds: 212681),
          text:
              'Imaan noticed a new student standing alone and invited her to join their group.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 212681),
          end: Duration(milliseconds: 217961),
          text:
              'Ali returned sports equipment instead of leaving it for someone else.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 217961),
          end: Duration(milliseconds: 221081),
          text: 'No one wrote these actions on a scoreboard.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 221081),
          end: Duration(milliseconds: 222681),
          text: 'No one handed out prizes.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 223329),
          end: Duration(milliseconds: 228129),
          text:
              'And that was exactly why Mrs. Farah’s test finally made sense.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 228129),
          end: Duration(milliseconds: 234803),
          text: 'Challenge of the Day: Thank Them While They Can Hear You',
        ),
        CaptionLine(
          start: Duration(milliseconds: 234803),
          end: Duration(milliseconds: 243297),
          text:
              'Mission: Choose one person who regularly helps, teaches, protects, supports or cares for you.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 243297),
          end: Duration(milliseconds: 250937),
          text:
              'Thank them today with one specific sentence about what they actually do, then follow the words with one helpful action.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 250937),
          end: Duration(milliseconds: 257697),
          text:
              'Level-Up (Ages 9-12): Choose someone you have assumed “already knows” you are grateful.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 257697),
          end: Duration(milliseconds: 259570),
          text: 'Tell them anyway.',
        ),
      ],
    ),
    Story(
      id: 'gratitude_en_10',
      title: 'Ep 10 · The Children Who Notice',
      narrator: 'Imaan & Akhlaq',
      coverAsset: 'assets/covers/gratitude.webp',
      audioAsset: 'assets/audio/en/gratitude/10_the_children_who_notice.ogg',
      category: StoryCategory.moral,
      description: 'The Things We Never Notice — episode 10 of 10.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 227),
          end: Duration(milliseconds: 1369),
          text: 'EPISODE 10',
        ),
        CaptionLine(
          start: Duration(milliseconds: 1369),
          end: Duration(milliseconds: 3695),
          text: 'The Children Who Notice',
        ),
        CaptionLine(
          start: Duration(milliseconds: 3695),
          end: Duration(milliseconds: 9695),
          text:
              'The mystery ends by turning gratitude into a responsibility that continues.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 9695),
          end: Duration(milliseconds: 13695),
          text: 'Gratitude Day arrived under a bright Amanpur sky.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 13695),
          end: Duration(milliseconds: 23663),
          text:
              'Banners hung across the school entrance, parents filled the courtyard and the Gratitude Wall had become a patchwork of hundreds of handwritten notes.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 23663),
          end: Duration(milliseconds: 27663),
          text: 'The Principal began the ceremony in an unusual way.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 27663),
          end: Duration(milliseconds: 40663),
          text:
              'Instead of calling high-scoring students or senior guests first, he invited the school helpers onto the stage: the cleaner, gardener, bus driver, office assistant, peon and security staff.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 40663),
          end: Duration(milliseconds: 46534),
          text:
              'Many looked uncomfortable standing where they were usually watching others stand.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 46534),
          end: Duration(milliseconds: 48071),
          text: 'The Principal smiled.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 48071),
          end: Duration(milliseconds: 54991),
          text:
              '“Today our guests of honour are people whose work becomes visible mostly when it stops.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 54991),
          end: Duration(milliseconds: 57794),
          text: 'The whole school stood and applauded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 57794),
          end: Duration(milliseconds: 63591),
          text:
              'Uncle Bashir wiped his eyes before Ali could tease him about it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 63599),
          end: Duration(milliseconds: 68699),
          text: 'Then Mrs. Shazia came forward holding Mrs. Farah’s diary.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 68699),
          end: Duration(milliseconds: 74639),
          text:
              'She told the audience that Farah had believed gratitude was not a single thank-you.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 74639),
          end: Duration(milliseconds: 77379),
          text: 'It was a way of seeing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 77379),
          end: Duration(milliseconds: 88847),
          text:
              'Before leaving the school, she had asked Uncle Bashir to protect her letter until another group of children began noticing kindness without needing prizes or instructions.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 88847),
          end: Duration(milliseconds: 93147),
          text: 'The mystery had never been about finding hidden treasure.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 93147),
          end: Duration(milliseconds: 96367),
          text: 'The letter itself was the test.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 96367),
          end: Duration(milliseconds: 99835),
          text: 'Uncle Bashir opened the final page and read:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 99835),
          end: Duration(milliseconds: 100991),
          text: 'Dear Children,',
        ),
        CaptionLine(
          start: Duration(milliseconds: 100991),
          end: Duration(milliseconds: 106735),
          text:
              'If these pages have reached you, then you have already discovered what I hoped you would learn.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 107615),
          end: Duration(milliseconds: 110815),
          text: 'Success is not only the trophy with your name on it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 111695),
          end: Duration(milliseconds: 122415),
          text:
              'Look behind every success and you will find people who cooked, cleaned, taught, carried, waited, corrected, protected, encouraged and believed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 125608),
          end: Duration(milliseconds: 143503),
          text: 'Begin with Alhamdulillah.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 143503),
          end: Duration(milliseconds: 143504),
          text:
              'Every blessing is from Allah, and gratitude to Him should make you better at appreciating the people He has placed in your life.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 143504),
          end: Duration(milliseconds: 143505),
          text: 'Thank your parents while they can hear you.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 143505),
          end: Duration(milliseconds: 143506),
          text: 'Respect your teachers while they can guide you.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 143506),
          end: Duration(milliseconds: 143507),
          text: 'Learn the names of people others overlook.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 143507),
          end: Duration(milliseconds: 147471),
          text: 'Take care of the things people work hard to provide.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 147471),
          end: Duration(milliseconds: 151471),
          text: 'And when kindness reaches you, do not let it stop with you.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 151471),
          end: Duration(milliseconds: 152471),
          text: 'Pass it on.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 154471),
          end: Duration(milliseconds: 159471),
          text:
              'The hall remained quiet for several seconds after Uncle Bashir finished.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 159471),
          end: Duration(milliseconds: 162471),
          text:
              'Then Imaan and Akhlaaq stepped onto the stage with Ali, Fatima and Hamza.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 163439),
          end: Duration(milliseconds: 167439),
          text: 'They unveiled a wooden board for the school entrance.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 167439),
          end: Duration(milliseconds: 171439),
          text: 'Across the top were the words THE CHILDREN WHO NOTICE.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 171439),
          end: Duration(milliseconds: 174439),
          text: 'Beneath them was a simple promise:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 174439),
          end: Duration(milliseconds: 175995),
          text: 'Notice kindness.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 175995),
          end: Duration(milliseconds: 177328),
          text: 'Appreciate it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 177328),
          end: Duration(milliseconds: 178439),
          text: 'Continue it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 178439),
          end: Duration(milliseconds: 182439),
          text: 'The board was not meant to honour five particular children.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 183407),
          end: Duration(milliseconds: 184488),
          text: 'The Principal made that clear.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 184488),
          end: Duration(milliseconds: 189919),
          text:
              'Any child could become one of “the children who notice” through daily choices.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 189919),
          end: Duration(milliseconds: 194390),
          text: 'A few weeks later, the Gratitude Wall remained in place.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 194390),
          end: Duration(milliseconds: 197935),
          text: 'Every Friday, students added new notes.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 197935),
          end: Duration(milliseconds: 203375),
          text: 'Some were emotional, some funny, some only a sentence long.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 203375),
          end: Duration(milliseconds: 208875),
          text:
              'More importantly, small behaviours around the school had begun to change.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 208875),
          end: Duration(milliseconds: 219875),
          text:
              'Children returned equipment, greeted helpers by name, included students standing alone and cleaned up after activities more often without being chased.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 219875),
          end: Duration(milliseconds: 222875),
          text: 'At home, the change remained too.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 223343),
          end: Duration(milliseconds: 229583),
          text:
              'Ammi was healthy again, but Imaan and Akhlaaq did not hand every responsibility back to her.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 231032),
          end: Duration(milliseconds: 234303),
          text:
              'Akhlaaq still filled water bottles and managed his school things.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 235569),
          end: Duration(milliseconds: 238783),
          text: 'Imaan still helped with preparation and checked on Dadi.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 239743),
          end: Duration(milliseconds: 244144),
          text:
              'Abbu smiled whenever he saw them doing something before Ammi asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 244144),
          end: Duration(milliseconds: 253593),
          text:
              'One afternoon, Uncle Bashir called the siblings beneath the old neem tree and handed them Mrs. Farah’s brass badge.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 254322),
          end: Duration(milliseconds: 255536),
          text: 'Akhlaaq stared at it.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 255536),
          end: Duration(milliseconds: 256751),
          text: '“Is this ours?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 256751),
          end: Duration(milliseconds: 260448),
          text: '“It is not a prize,” Uncle Bashir replied.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 260448),
          end: Duration(milliseconds: 261999),
          text: '“It is a reminder.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 261999),
          end: Duration(milliseconds: 266459),
          text: 'When you stop noticing people, it means nothing.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 266981),
          end: Duration(milliseconds: 268939),
          text: 'Imaan held it carefully.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 268939),
          end: Duration(milliseconds: 271619),
          text: '“Then maybe it should stay at school.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 271619),
          end: Duration(milliseconds: 273579),
          text: 'Uncle Bashir smiled.',
        ),
        CaptionLine(
